  if (a.tag == SUPER_TAG_INT && b.tag == SUPER_TAG_FLOAT)
    return super_bool(fabs((double)a.as.i - b.as.f) < 1e-9);
  if (a.tag == SUPER_TAG_FLOAT && b.tag == SUPER_TAG_INT)
    return super_bool(fabs(a.as.f - (double)b.as.i) < 1e-9);
