  if (a.tag == SUPER_TAG_INT && b.tag == SUPER_TAG_INT)
    return super_int(a.as.i - b.as.i);
  if (a.tag == SUPER_TAG_FLOAT || b.tag == SUPER_TAG_FLOAT)
    return super_float(super_as_f(a) - super_as_f(b));
