      if (a->kind == 1) a->f64s[(size_t)iidx] = (val.tag == SUPER_TAG_FLOAT) ? val.as.f : (double)val.as.i;
      else if (a->kind == 2) a->i64s[(size_t)iidx] = (val.tag == SUPER_TAG_INT) ? val.as.i : (int64_t)((val.tag == SUPER_TAG_FLOAT) ? val.as.f : 0);
